159: function loadState() {
160:   const saved = localStorage.getItem("joy_blob_state");
161:   if (saved) {
162:     try {
163:       state = JSON.parse(saved);
164:       state.inventory = state.inventory || {};
165:       state.ownedAccessories = state.ownedAccessories || { ...DEFAULT_STATE.ownedAccessories };
166:       state.equippedAccessories = state.equippedAccessories || { ...DEFAULT_STATE.equippedAccessories };
167:       state.diaryLogs = state.diaryLogs || [];
168:       state.activeMoodQuests = state.activeMoodQuests || [];
169:       state.moodQuestProgress = state.moodQuestProgress || {};
170:       state.stressHistory = state.stressHistory || [];
171:       state.activePosition = state.activePosition || "pos-carpet";
172:       
173:       checkDailyReset();
174:     } catch (e) {
175:       console.error("Error loading state, resetting...", e);
176:       state = { ...DEFAULT_STATE };
177:       saveState();
178:     }
179:   } else {
180:     state = { ...DEFAULT_STATE };
181:     state.lastResetDate = new Date().toDateString();
182:     saveState();
183:   }
184: }
185: 
186: function saveState() {
187:   localStorage.setItem("joy_blob_state", JSON.stringify(state));
188:   updateUI();
189: }
