191: function checkDailyReset() {
192:   const todayStr = new Date().toDateString();
193:   if (state.lastResetDate !== todayStr) {
194:     // Reset daily quests & limit
195:     state.activeMoodQuests = [];
196:     state.moodQuestProgress = {};
197:     state.grandQuestClaimed = false;
198:     state.playLimit = 3;
199:     state.fosteredDays = (state.fosteredDays || 1) + 1;
200:     state.lastResetDate = todayStr;
201:     saveState();
202:   }
203: }
