209: function getEquippedBonuses() {
210:   let bonusAtk = 0;      // EXP percent
211:   let bonusCoin = 0;     // COIN percent
212:   let maxHpBonus = 0;    // Max HP
213:   let maxEnergyBonus = 0;// Max Energy
214:   
215:   if (state.equippedAccessories.wizard_hat) {
216:     bonusAtk += 10;
217:     maxEnergyBonus += 5;
218:   }
219:   if (state.equippedAccessories.glasses) {
220:     bonusCoin += 10;
221:   }
222:   if (state.equippedAccessories.crown) {
223:     maxHpBonus += 15;
224:   }
225:   
226:   return { bonusAtk, bonusCoin, maxHpBonus, maxEnergyBonus };
227: }
