229: function updateMaxStats() {
230:   const bonuses = getEquippedBonuses();
231:   state.hpMax = 50 + bonuses.maxHpBonus;
232:   state.energyMax = 50 + bonuses.maxEnergyBonus;
233:   
234:   state.hp = Math.min(state.hpMax, state.hp);
235:   state.energy = Math.min(state.energyMax, state.energy);
236: }
