238: function gainExp(amount) {
239:   const bonuses = getEquippedBonuses();
240:   const actualAmount = Math.floor(amount * (1.0 + bonuses.bonusAtk / 100));
241:   
242:   state.exp += actualAmount;
243:   if (state.exp >= state.expMax) {
244:     state.exp -= state.expMax;
245:     state.level += 1;
246:     state.expMax = (state.level === 0 ? 100 : state.level * 40 + 100);
247:     triggerPetAnimation("happy");
248:     setPetBubbleText(`à¹€à¸¢à¹‰! à¸£à¹ˆà¸²à¸‡à¸à¸²à¸¢à¹€à¸›à¸¥à¹ˆà¸‡à¸›à¸£à¸°à¸à¸²à¸¢... à¹€à¸¥à¹€à¸§à¸¥à¹€à¸žà¸´à¹ˆà¸¡à¸‚à¸¶à¹‰à¸™à¹à¸¥à¹‰à¸§ à¸•à¸­à¸™à¸™à¸µà¹‰à¹€à¸¥à¹€à¸§à¸¥ ${state.level} à¹à¸¥à¹‰à¸§à¸™à¸°! ðŸŽ‰âœ¨`);
249:     updateEvolutionVisuals();
250:   }
251:   saveState();
252: }
253: 
254: function modifyCoins(amount) {
255:   const bonuses = getEquippedBonuses();
256:   const actualAmount = amount > 0 ? Math.floor(amount * (1.0 + bonuses.bonusCoin / 100)) : amount;
257:   state.coins = Math.max(0, state.coins + actualAmount);
258:   saveState();
259: }
260: 
261: function modifyGems(amount) {
262:   state.gems = Math.max(0, state.gems + amount);
263:   saveState();
264: }
265: 
266: function modifyHp(amount) {
267:   updateMaxStats();
268:   state.hp = Math.max(0, Math.min(state.hpMax, state.hp + amount));
269:   saveState();
270: }
271: 
272: function modifyEnergy(amount) {
273:   updateMaxStats();
274:   state.energy = Math.max(0, Math.min(state.energyMax, state.energy + amount));
275:   saveState();
276: }
