317: function switchTab(tabId) {
318:   document.querySelectorAll(".view-panel").forEach(panel => {
319:     panel.classList.remove("active");
320:   });
321:   document.querySelectorAll(".nav-tab").forEach(tab => {
322:     tab.classList.remove("active");
323:   });
324:   
325:   const targetPanel = document.getElementById(`view-${tabId}`);
326:   if (targetPanel) {
327:     targetPanel.classList.add("active");
328:   }
329:   const targetTab = document.querySelector(`.nav-tab[data-tab="${tabId}"]`);
330:   if (targetTab) {
331:     targetTab.classList.add("active");
332:   }
333: 
334:   // Load sub-features
335:   if (tabId === "diary") {
336:     setupDiaryCalendar();
337:     renderDiaryLogs();
338:   } else if (tabId === "quest") {
339:     checkAndGenerateMoodQuests();
340:     renderQuests();
341:   } else if (tabId === "shop") {
342:     renderShop("food");
343:   } else if (tabId === "game") {
344:     document.getElementById("gameIntroSec").style.display = "flex";
345:     document.getElementById("memoryGamePlaySec").style.display = "none";
346:     document.getElementById("playLimitVal").innerText = `${state.playLimit}/3`;
347:   }
348: }
